import test from'node:test';import assert from'node:assert/strict';
import{initialState,activeSession,transition,normalizeState,serializeSession,parseSession,markdown}from'./state.js';
import{make,validate}from'../questions/state.js';
import{portable}from'../creative-kit/state.js';
import{parseQuestions,readQuestionWorkspaces}from'./inquiry.js';
test('old Questions work arrives as a new problem with answers, evidence, ancestry and selection intact',()=>{const workspace=make('old');workspace.items[0].answer='A provisional answer';workspace.items[0].evidence='A field observation';workspace.items[0].ideas='A different operating rule';workspace.phase='develop';const old=JSON.stringify({version:1,activeId:'old',workspaces:[workspace]});const state=initialState(),before=structuredClone(state);const imported=transition(state,{type:'import-questions',workspace:readQuestionWorkspaces(old)[0],id:'new'});assert.deepEqual(state,before);assert.equal(imported.sessions.length,2);assert.deepEqual(activeSession(imported).inquiry.items,workspace.items);assert.deepEqual(activeSession(imported).inquiry.selected,workspace.selected);assert.equal(activeSession(imported).inquiry.phase,'develop');assert.equal(activeSession(imported).sources[0].workspaceId,'old');assert.deepEqual(parseQuestions(portable(workspace,'questions',validate)),workspace);assert.ok(markdown(activeSession(imported)).includes('A field observation'));});
test('connections and branch snapshots survive export/import with references remapped',()=>{let s=initialState();const q=activeSession(s).inquiry.items[0];s=transition(s,{type:'inquiry',action:{type:'link',questionId:q.id,frameId:activeSession(s).frames[0].id,relation:'challenges'}});s=transition(s,{type:'frame-from-question',id:'from-q',questionId:q.id});s=transition(s,{type:'branch-frame',id:'branch',parent:'from-q'});const before=structuredClone(activeSession(s));const imported=parseSession(serializeSession(before));assert.deepEqual(imported,before);s=transition(s,{type:'import-session',id:'copy',session:imported});const next=activeSession(s);assert.equal(next.inquiry.items[0].id,'copy-q1');assert.equal(next.frames[3].origin.sourceId,'copy-q1');assert.equal(next.frames[4].origin.sourceId,'copy-f4');// Editing a connection may reorder the link list; its endpoints define identity.
assert.equal(next.inquiry.links.find(l=>l.questionId==='copy-q1'&&l.frameId==='copy-f1').relation,'challenges');assert.deepEqual(normalizeState(JSON.parse(JSON.stringify(s))),s);});
test('challenging a question preserves its parent without inventing a supposed opposite',()=>{const s=initialState(),parent=activeSession(s).inquiry.items[0];const next=transition(s,{type:'inquiry',action:{type:'branch',id:'child',parent:parent.id,relation:'invert'}});const q=activeSession(next).inquiry.items.at(-1);assert.equal(q.question,'');assert.equal(q.parent,parent.id);assert.equal(q.relation,'invert');assert.equal(activeSession(next).inquiry.items[0].question,parent.question);});
test('source edits do not overwrite a derived frame or its source snapshot',()=>{let s=initialState();s=transition(s,{type:'inquiry',action:{type:'edit',item:'q1',field:'answer',value:'Initial interpretation'}});s=transition(s,{type:'frame-from-question',id:'derived',questionId:'q1'});s=transition(s,{type:'inquiry',action:{type:'edit',item:'q1',field:'answer',value:'A later interpretation'}});const f=activeSession(s).frames.at(-1);assert.equal(f.statement,'Initial interpretation');assert.equal(f.origin.snapshot.answer,'Initial interpretation');});
test('invalid connections and imported dangling references fail before state changes',()=>{const s=initialState();assert.throws(()=>transition(s,{type:'inquiry',action:{type:'link',questionId:'missing',frameId:activeSession(s).frames[0].id,relation:'opens'}}),/inconsistent/);const bad=JSON.parse(serializeSession(activeSession(s)));bad.session.inquiry.links[0].frameId='missing';assert.throws(()=>parseSession(JSON.stringify(bad)),/inconsistent/);});
test('legacy Reframing saves keep all frames and tests while acquiring an empty inquiry',()=>{const old=initialState();for(const s of old.sessions){delete s.inquiry;delete s.sources;s.frames.forEach(f=>delete f.origin);s.view='plan';}const migrated=normalizeState(old);assert.equal(activeSession(migrated).inquiry.items.length,0);assert.equal(activeSession(migrated).view,'plan');assert.equal(activeSession(migrated).frames[0].statement,activeSession(old).frames[0].statement);assert.deepEqual(activeSession(migrated).plan,activeSession(old).plan);});
